<body>
  <div class="app">
    <header class="header">
      <div class="header__inner">
        <h1>عنوان التوصيل</h1>
        <p>أدخل تفاصيل موقع تسليم الطلب.</p>
      </div>
    </header>

    <main>
      <form class="card" id="addressForm" novalidate>
        <div class="field">
          <label for="building">المبنى أو الفيلا</label>
          <input
            id="building"
            name="building"
            type="text"
            inputmode="text"
            autocomplete="address-line2"
            placeholder="مثال: فيلا 12 أو برج النخيل"
            required
          >
          <p class="error-message" id="buildingError">يرجى إدخال اسم المبنى أو الفيلا.</p>
        </div>

        <div class="field">
          <label for="street">الشارع</label>
          <input
            id="street"
            name="street"
            type="text"
            inputmode="text"
            autocomplete="address-line1"
            placeholder="اسم الشارع"
            required
          >
          <p class="error-message" id="streetError">يرجى إدخال اسم الشارع.</p>
        </div>

        <div class="field">
          <label for="area">المنطقة</label>
          <input
            id="area"
            name="area"
            type="text"
            inputmode="text"
            autocomplete="address-level3"
            placeholder="اسم المنطقة"
            required
          >
          <p class="error-message" id="areaError">يرجى إدخال اسم المنطقة.</p>
        </div>

        <div class="field">
          <label for="makani">
            رقم-location
            <span class="optional">(اختياري)</span>
          </label>
          <input
            id="makani"
            name="makani"
            type="text"
            inputmode="numeric"
            autocomplete="off"
            placeholder="أدخل رقم-location"
          >
        </div>

        <div class="field">
          <label for="emirate">الإمارة</label>
          <select id="emirate" name="emirate" autocomplete="address-level1">
            <option value="dubai" selected>دبي</option>
            <option value="abu-dhabi">أبوظبي</option>
            <option value="sharjah">الشارقة</option>
            <option value="ajman">عجمان</option>
            <option value="umm-al-quwain">أم القيوين</option>
            <option value="ras-al-khaimah">رأس الخيمة</option>
            <option value="fujairah">الفجيرة</option>
          </select>
        </div>

        <div class="field">
          <label for="phone">رقم الهاتف</label>
          <div class="phone-wrap">
            <span class="phone-prefix" aria-hidden="true">+971</span>
            <input
              id="phone"
              name="phone"
              type="tel"
              inputmode="tel"
              autocomplete="tel"
              dir="ltr"
              aria-describedby="phoneHint phoneError"
              placeholder="050 123 4567"
              required
            >
          </div>
          <p class="hint" id="phoneHint">مثال: <bdi dir="ltr">050 123 4567</bdi></p>
          <p class="error-message" id="phoneError">يرجى إدخال رقم هاتف إماراتي صحيح.</p>
        </div>

        <button class="save-button" type="submit">حفظ العنوان</button>
      </form>
    </main>
  </div>

  <div class="toast" id="toast" role="status" aria-live="polite">
    تم حفظ عنوان التوصيل بنجاح.
  </div>

  <script>
    const form = document.getElementById("addressForm");
    const phoneInput = document.getElementById("phone");
    const toast = document.getElementById("toast");

    function setError(inputId, errorId, show) {
      const input = document.getElementById(inputId);
      const error = document.getElementById(errorId);
      input.setAttribute("aria-invalid", show ? "true" : "false");
      error.classList.toggle("visible", show);
    }

    function validateText(id, errorId) {
      const input = document.getElementById(id);
      const valid = input.value.trim().length > 0;
      setError(id, errorId, !valid);
      return valid;
    }

    function normalizeDigits(value) {
      return value
        .replace(/[٠-٩]/g, digit => String(digit.charCodeAt(0) - 0x0660))
        .replace(/[۰-۹]/g, digit => String(digit.charCodeAt(0) - 0x06F0))
        .replace(/\D/g, "");
    }

    function validatePhone() {
      const digits = normalizeDigits(phoneInput.value);
      const localNumber = digits.startsWith("00971")
        ? digits.slice(5)
        : digits.startsWith("971")
          ? digits.slice(3)
          : digits.startsWith("0")
            ? digits.slice(1)
            : digits;

      const valid = /^5[024568]\d{7}$/.test(localNumber);
      setError("phone", "phoneError", !valid);
      return valid;
    }

    phoneInput.addEventListener("input", function () {
      this.value = this.value.replace(/[^\d٠-٩۰-۹+\-\s()]/g, "");
      if (this.getAttribute("aria-invalid") === "true") {
        validatePhone();
      }
    });

    form.addEventListener("submit", function (event) {
      event.preventDefault();

      const results = [
        validateText("building", "buildingError"),
        validateText("street", "streetError"),
        validateText("area", "areaError"),
        validatePhone()
      ];

      if (results.includes(false)) {
        const firstInvalid = form.querySelector('[aria-invalid="true"]');
        firstInvalid.focus();
        return;
      }

      toast.classList.add("show");
      window.setTimeout(() => toast.classList.remove("show"), 3000);
    });
  </script>
</body>
</html>
